from collections import Counter

def analyze_olympic_participation():
    athletes = [
        {'name': 'Beth', 'age': 20, 'team': 'USA'},
        {'name': 'Anna', 'age': 18, 'team': 'Chile'},
        {'name': 'Kim', 'age': 25, 'team': 'Japan'},
    ]

    teams = [athlete['team'] for athlete in athletes]

    team_counts = Counter(teams)
    for team, count in team_counts.items():
        print(f"{team}: {count} athletes")

if __name__ == '__main__':
    analyze_olympic_participation()

