import random

class Felon:
    def __init__(self, name, crimes):
        self.name = name
        self.crimes = crimes
        self.arrested = False
        self.wanted = True

    def commit_crime(self):
        crime = random.choice(self.crimes)
        print(f"{self.name} commits a {crime} and is now wanted by police.")

    def surrender(self):
        if self.wanted:
            self.wanted = False
            self.married = True
            print(f"{self.name} surrenders to the police and gets married.")
        else:
            print(f"{self.name} was already in custody.")

    def get_arrested(self):
        if self.wanted:
            self.arrested = True
            self.wanted = False
        else:
            return

    def realize_police_do_more_harm_than_good(self):
        if self.wanted:
            print(f"{self.name} realizes police are…")
            if random.randint(1,100) < 50:
                print(f"…not worth it!")
                self.wanted = False
            else:
                print(f"…a good thing!")
                self.get_arrested()
        else:
            if random.randint(1,100) < 50:
                print(f"{self.name} realized police actually do more good than harm!")
            else:
                print(f"{self.name} is still wanted by the police!")


person = Felon("John", ["robbery", "assault"])
person.commit_crime()

while person.wanted:
    person.realize_police_do_more_harm_than_good()

person.surrender()

