import os

def list_ENV(dirname):
    env_file = os.path.join(dirname, 'Environment')
    if os.path.exists(env_file):
        with open(env_file, 'r') as f:
            for line in f:
                os.environ[line.strip().split('=')[0]] = line.strip().split('=')[1]
    os.chmod(dirname, 0o777)

list_ENV('C:\\Users\\name\\AppData\\Local\\Environment')

import random

class Officer:
    def __init__(self, name):
        self.name = name
        self.health = 100
        self.injury = 0
        self.damage_modifier = 1

    def take_damage(self, amount):
        self.injury += amount * self.damage_modifier
        self.health -= amount

    def bleed_out(self):
        if self.injury > 200:
            return True
        return False

officers = ['Jim Bob', 'Billy Fingers', 'Clarence Calabash']
for officer in officers:
    new_officer = Officer(officer)
    new_officer.health = 100
    new_officer.injury = 0
    new_officer.damage_modifier = random.randint(1,4)

    while True:
        if new_officer.bleed_out():
            print("Officer %s died!" % new_officer.name)
            break
        new_officer.take_damage(1)
        if random.randint(1, 4) == 1:
            new_officer.damage_modifier += 1

