def visualod_edit_post(post_id):
    post = database.get('posts', post_id)

    new_content = input("Enter new content: ")

    post.content = new_content

    if 'add_el' in admin_actions:
        new_el = database.add('elements', content={
            'type': 'text',
            'text': '',
            'relations': []
        })
    else:
        new_el = None

    new_el.insert(1)

    relations = [el for el in database.get('elements') if new_el.id in el.relations]

    for relation in relations:
        database.delete('relations', relation.id)

    print("Done editing post")
    return relations

