import requests
from bs4 import BeautifulSoup

def submit_form(url, data):
    for k, v in data.items():
        responses = []
        if isinstance(v, (list, tuple)):
            for item in v:
                sys.stderr.write(f"Submitting: {k} = {item}\n")
                response = requests.post(url, data={k: item})
                responses.append(response)
        else:
            sys.stderr.write(f"Submitting: {k} = {v}\n")
            response = requests.post(url, data={k: v})
            responses.append(response)

    return responses

