import socket
from _testcapi import INT_MAX

def get_ips_in_range(ip_range) -> list:
    ip_list = []
    if '-' in ip_range:
        first_ip, last_ip = ip_range.split('-')
    else:
        first_ip, last_ip = ip_range, ip_range

    if '/' in first_ip:
        ip_parts = first_ip.split('/')
        first_ip = ip_parts[0]
        cidr = int(ip_parts[1])
    else:
        ip_parts = first_ip.split('.')
        cidr = 24
        first_ip = socket.inet_aton(ip_parts[0])
        if cidr > 32:
            cidr = 32

    for ip in range(first_ip,(((2**32)>>cidr)+1)<<cidr):
        new_ip = socket.inet_ntoa(ip)
        if new_ip >= first_ip and new_ip <= last_ip:
            ip_list.append(new_ip)

    return ip_list

