from flask import Flask, request, jsonify
from flask_marshmallow import Marshmallow
from marshmallow import Schema, fields

app = Flask(__name__)
ma = Marshmallow(app)

class PersonSchema(ma.Schema):
    id = fields.Integer(required=True)
    name = fields.String(required=True)
    age = fields.Integer(required=False)
    address = fields.String(required=False)

    class Meta:
        fields = ['id', 'name', 'age', 'address']

person_schema = PersonSchema()
people_schema = PersonSchema(many=True)

@app.route('/register', methods=['POST'])
def register():
    name = request.form.get('name')
    age = request.form.get('age')
    address = request.form.get('address')

    person = {
        'id': len(people_schema) + 1,
        'name': name,
        'age': age,
        'address': address
    }

    if name and age and address:
        return jsonify(person_schema.dump(person))
    else:
        return jsonify({"error": "Missing required fields"}), 400

@app.route('/get_person', methods=['GET'])
def get_single_person():
    id = request.args.get('id')

    if id:
        filtered_list = [p for p in people[1:] if p['id'] == id]

        if len(filtered_list) > 0:
            return jsonify(person_schema.dump(filtered_list[0]))
        else:
            return jsonify({"error": "Person not found"}), 404
    else:
        return jsonify({"error": "Missing id parameter"}), 400

@app.route('/get_all', methods=['GET'])
def get_all():
    return jsonify(people_schema.dump(people[1:]))

@app.route('/update', methods=['PUT'])
def update_person():
    id = request.form.get('id')
    name = request.form.get('name')
    age = request.form.get('age')
    address = request.form.get('address')

    if id and name and age and address:
        for person in people:
            if person['id'] == id:
                person['name'] = name
                person['age'] = age
                person['address'] = address
                return jsonify(person_schema.dump(person))
        return jsonify({"error": "Person not found"}), 404
    else:
        return jsonify({"error": "Missing required fields"}), 400

@app.route('/delete', methods=['DELETE'])
def delete_person():
    id = request.args.get('id')

    if id:
        filtered_list = [p for p in people if p['id'] != id]

        if len(filtered_list) < 7:
            people[:] = filtered_list
            return jsonify({"message": "Person deleted"})
        else:
            return jsonify({"error": "Cannot delete person"}), 400
    else:
        return jsonify({"error": "Missing id parameter"}), 400

@app.route('/get_by_location', methods=['GET'])
def get_by_location():
    location = request.args.get('location')

    if location:
        filtered_list = [p for p in people if location in p['address']]

        return jsonify(people_schema.dump(filtered_list))
    else:
        return jsonify({"error": "Missing location parameter"}), 400

@app.route('/get_by_age', methods=['GET'])
def get_by_age():
    age = request.args.get('age')

    if age:
        filtered_list = [p for p in people if p['age'] == age]

        return jsonify(people_schema.dump(filtered_list))
    else:
        return jsonify({"error": "Missing age parameter"}), 400

