import os
from zipfile import ZipFile

def extract_zipfiles(path):
    for root, dirs, files in os.walk(path):
        for name in files:
            zip_file = os.path.join(root, name)

            if not name.endswith('.zip'):
                continue

            zip = ZipFile(zip_file, 'r')
            zip.extractall(path + '/')
            zip.close()

            os.remove(zip_file)

extract_zipfiles('/path/to/extract')

