import re
import collections

def count_starts_with(pattern, strings):
    counter = collections.defaultdict(int)
    for string in strings:
        if string[0] == pattern:
            counter[string] += 1
    return counter

count_starts_with("(?:\s*,\s*)*", ["marijuana", "marihuana"])

